mapper.sql:
where 1=1

		and cpvc_llave = #{llaveTabla}


		and cpvc_estado = #{estado}


		and cpvc_documento = #{documento}


		and cpvc_campo = #{campo}


		and cpvc_valortext = #{valorText}


		and dpvc_valorfecha >= #{valorFechaMin}


		and dpvc_valorfecha  <   #{valorFechaMax}


		and cpvc_valoropcion = #{valorOpcion}


		and cpvc_valorauxiliar = #{valorAuxiliar}


		and cpvc_transaccionregistro = #{transaccionRegistro}


		and cpvc_transaccioninactivo = #{transaccionInactivo}

mapper.select:
insert into pedidoventacaracteristica_pvcp(
	cpvc_llave

	,cpvc_documento


	,cpvc_campo


	,cpvc_valortext


	,dpvc_valorfecha


	,cpvc_valoropcion


	,cpvc_valorauxiliar


	,mpvc_valornumero


	,cpvc_transaccionregistro


	,cpvc_transaccioninactivo


	,cpvc_estado

) values (
	#{llaveTabla}

	,#{documento}


	,#{campo}


	,#{valorText}


	,#{valorFecha}


	,#{valorOpcion}


	,#{valorAuxiliar}


	,#{valorNumero}


	,#{transaccionRegistro}


	,#{transaccionInactivo}


	,#{estado}

)

select cpvc_documento from pedidoventacaracteristica_pvcp a
where cpvc_campo = #{campo} and cpvc_estado = 'A' and cpvc_valortext = #{valorText}
and cpvc_llave != #{llaveTabla}
limit 1

insert into historic.z_pvc_pedidoventacaracteristica(
	cpvc_llave

	,cpvc_documento


	,cpvc_campo


	,cpvc_valortext


	,dpvc_valorfecha


	,cpvc_valoropcion


	,cpvc_valorauxiliar


	,mpvc_valornumero


	,cpvc_transaccionregistro


	,cpvc_transaccioninactivo


	,cpvc_estado

) values (
	#{llaveTabla}

	,#{documento}


	,#{campo}


	,#{valorText}


	,#{valorFecha}


	,#{valorOpcion}


	,#{valorAuxiliar}


	,#{valorNumero}


	,#{transaccionRegistro}


	,#{transaccionInactivo}


	,#{estado}

)

select dc.cdpc_llave  from documentoplantillacaracteristica_dpcp dc
		inner join documentoplantilla_dplp dp on dp.cdpl_llave = dc.cdpc_plantilla 
	where dc.cdpc_codigo = #{pCode}
		and dp.cdpl_codigo = #{pTemplate}

select cpvc_documento from pedidoventacaracteristica_pvcp pp 
where pp.cpvc_estado = 'A' and pp.cpvc_valoropcion = #{pValue}
and pp.cpvc_campo = #{pCodeKey}
